13	
14	// 本文件锁定“归档读取”侧缺陷记录文本成员的类型规则。ReportFinding 的
15	// artifactHash、ruleId、version、severity、invariant、evidence 全是 Go 字符串，
16	// json.Unmarshal 会把正式成员的 null 静默解码成零值 ""：当一份合法报告的
17	// 规则与缺陷记录都把 severity（或 invariant）保存为空字符串时，只把 findings
18	// 中对应记录的该成员改成 null，产物哈希、报告标识与规则/缺陷归属仍然全部
19	// 吻合，归档没有保存合法文本却被当成合法空文本读回，diff 甚至可能把它判成
20	// “无变化”。
21	//
22	// 修正后，正式成员（约定拼写，含 Unicode 转义写法）一旦写出，其值就必须是
23	// JSON 字符串；null、布尔值、数字、对象、数组都使整份归档判为损坏，即使产物
24	// 哈希、报告标识以及规则与缺陷的对应关系仍吻合也不例外。错误点名请求的报告
25	// 标识、出错记录在 findings 数组中从零开始的位置和成员名，明确该成员必须是
26	// 字符串；记录的 ruleId 本身是合法非空字符串时，还要指出所属规则。成员省略
27	// 或显式写成空字符串时，继续按原有必填和绑定要求判断，不新增所有文本必须
28	// 非空的限制。大小写变体、两侧带空格的名称和未知成员仍作为扩展信息忽略，
29	// 不能替代缺失字段或挽救非法正式值。
30	
31	// jsonEscapedS is the six-character JSON unicode escape that decodes to the
32	// letter s; it is built by concatenation so the source never carries the
33	// escape-looking literal as one piece.
34	const jsonEscapedS = `\` + `u0073`
35	
36	// mutateFindingField 把归档 findings 中指定记录（按其当前 ruleId 定位）的某个
37	// 文本成员替换为 raw 片段（如 null）；该成员不存在时把它插入到记录对象开头。
38	// fragment 为空串表示删除整个成员。
39	func mutateFindingField(t *testing.T, doc, ruleID, field, fragment string) string {
40		t.Helper()
41		findingsAt := strings.Index(doc, `"findings"`)
42		if findingsAt < 0 {
43			t.Fatal("test setup: archive has no findings member")
44		}
45		idMember := `"ruleId":"` + ruleID + `"`
46		idIdx := strings.Index(doc[findingsAt:], idMember)
47		if idIdx < 0 {
48			t.Fatalf("test setup: finding for rule %s not found in archive", ruleID)
49		}
50		idIdx += findingsAt
51		recStart := strings.LastIndexByte(doc[findingsAt:idIdx], '{')
52		if recStart < 0 {
53			t.Fatalf("test setup: finding for rule %s object has no start", ruleID)
54		}
55		recStart += findingsAt
56		recEnd := strings.IndexByte(doc[idIdx:], '}')
57		if recEnd < 0 {
58			t.Fatalf("test setup: finding for rule %s object has no end", ruleID)
59		}
60		recEnd += idIdx
61		marker := `"` + field + `":`
62		at := strings.Index(doc[recStart:recEnd], marker)
63		if at < 0 {
64			if fragment == "" {
65				t.Fatalf("test setup: finding for rule %s has no %s member to remove", ruleID, field)
66			}
67			// 成员不存在：插到记录对象的开括号之后。
68			insertAt := recStart + 1
69			return doc[:insertAt] + `"` + field + `":` + fragment + `,` + doc[insertAt:]
70		}
71		at += recStart
72		valueStart := at + len(marker)
73		var valueEnd int
74		if doc[valueStart] == '"' {
75			// 测试夹具中的字符串值不含转义引号，下一个引号即结束。
76			closing := strings.IndexByte(doc[valueStart+1:], '"')
77			if closing < 0 {
78				t.Fatalf("test setup: finding for rule %s %s value has no closing quote", ruleID, field)
79			}
80			valueEnd = valueStart + 1 + closing + 1
81		} else {
82			end := strings.IndexAny(doc[valueStart:], ",}")
83			if end < 0 {
84				t.Fatalf("test setup: finding for rule %s %s value has no end", ruleID, field)
85			}
86			valueEnd = valueStart + end
87		}
88		if fragment == "" {
89			// 删除整个成员：优先连同后随逗号，否则连同前导逗号。
90			if valueEnd < len(doc) && doc[valueEnd] == ',' {
91				return doc[:at] + doc[valueEnd+1:]
92			}
93			return doc[:at-1] + doc[valueEnd:]
94		}
95		return doc[:at] + `"` + field + `":` + fragment + doc[valueEnd:]
96	}
97	
98	// writeArchiveWithFindingText marshals a legal report, rewrites one finding
99	// text member with a raw fragment, recomputes the report id from the decoded
100	// content and writes the archive under that id. A null fragment launders
101	// through the plain decoder (null decodes into the string zero value), so the
102	// recomputed id keeps the archive self-consistent and rejection can only come
103	// from the type gate. Other non-string JSON types never unmarshal into a Go
104	// string, so the original id is kept: it may mismatch, but the type gate runs
105	// before the id comparison and rejects with the same corruption error.
106	func writeArchiveWithFindingText(t *testing.T, dir string, r Report, ruleID, field, fragment string) string {
107		t.Helper()
108		r.ReportID = ReportID(r)
109		data, err := json.Marshal(r)
110		if err != nil {
111			t.Fatal(err)
112		}
113		doc := mutateFindingField(t, string(data), ruleID, field, fragment)
114		if doc == string(data) {
115			t.Fatal("test setup: mutation did not change the archive")
116		}
117		id := r.ReportID
118		if strict, err := strictReportJSON([]byte(doc)); err == nil {
119			var decoded Report
120			if err := json.Unmarshal(strict, &decoded); err == nil {
121				newID := ReportID(decoded)
122				doc = strings.Replace(doc, `"reportId":"`+id+`"`, `"reportId":"`+newID+`"`, 1)
123				id = newID
124			}
125		}
126		if err := os.WriteFile(filepath.Join(dir, id+".json"), []byte(doc), 0o644); err != nil {
127			t.Fatal(err)
128		}
129		return id
130	}
131	
132	// expectCorruptFindingTextLoad asserts the full read-side contract for a
133	// non-string formal finding text member: errCorrupt naming the report id, the
134	// findings array position, the field and the string requirement (plus the rule
135	// id when the record carries a legal one), a zero report and an untouched
136	// archive.
137	func expectCorruptFindingTextLoad(t *testing.T, dir, id, position, rule, field string) {
138		t.Helper()
139		path := filepath.Join(dir, id+".json")
140		before, err := os.ReadFile(path)
141		if err != nil {
142			t.Fatal(err)
143		}
144		got, err := LoadReport(dir, id)
145		if err == nil {
146			t.Fatalf("a non-string formal finding %s must reject the whole archive, got %+v", field, got)
147		}
148		var ec errCorrupt
149		if !errors.As(err, &ec) {
150			t.Fatalf("illegal finding %s classifies as errCorrupt, got %T: %v", field, err, err)
151		}
152		msg := err.Error()
153		if !strings.Contains(msg, id) {
154			t.Fatalf("error must name the report id %q: %v", id, err)
155		}
156		if !strings.Contains(msg, position) {
157			t.Fatalf("error must name the findings array position %q: %v", position, err)
158		}
159		if rule != "" && !strings.Contains(msg, rule) {
160			t.Fatalf("error must name the owning rule %q: %v", rule, err)
161		}
162		if !strings.Contains(msg, field+" must be a string") {
163			t.Fatalf("error must state %s must be a string: %v", field, err)
164		}
165		if !reflect.DeepEqual(got, Report{}) {
166			t.Fatalf("failed read must return the zero report, got %+v", got)
167		}
