612			t.Fatalf("restored archive must diff successfully: %v", err)
613		}
614		if diff.Summary.AddedRules+diff.Summary.RemovedRules+diff.Summary.ChangedRules == 0 {
615			t.Fatalf("expected rule-set differences between the two legal reports, got %+v", diff.Summary)
616		}
617		afterRestore, err := os.ReadFile(filepath.Join(dir, otherID+".json"))
618		if err != nil {
619			t.Fatal(err)
620		}
621		if !bytes.Equal(afterRestore, cleanOther) {
622			t.Fatal("successful diff must not rewrite the archive")
623		}
624	}
625	
626	// --- audit 保存遇到同标识已有损坏归档：不能被当成保存成功，原文件保留 ---
627	
628	func TestSaveReportBadFindingTextExistingArchiveFails(t *testing.T) {
629		dir := t.TempDir()
630		id := writeArchiveWithFindingText(t, dir, emptySeverityFixture(), "r-empty", "severity", `null`)
631		path := filepath.Join(dir, id+".json")
632		before, err := os.ReadFile(path)
633		if err != nil {
634			t.Fatal(err)
635		}
636	
637		r := emptySeverityFixture()
638		r.ReportID = id
639		err = SaveReport(dir, r)
640		if err == nil {
641			t.Fatal("a corrupt existing archive must not count as a successful save")
642		}
643		var ec errCorrupt
644		if !errors.As(err, &ec) {
645			t.Fatalf("expected errCorrupt, got %T: %v", err, err)
646		}
647		if !strings.Contains(err.Error(), id) || !strings.Contains(err.Error(), "r-empty") ||
648			!strings.Contains(err.Error(), "findings[0]") ||
649			!strings.Contains(err.Error(), "severity must be a string") {
650			t.Fatalf("error must name the report, position, rule and string requirement: %v", err)
651		}
652		after, err := os.ReadFile(path)
653		if err != nil {
654			t.Fatalf("corrupt archive must be kept: %v", err)
655		}
656		if string(after) != string(before) {
657			t.Fatal("failed save must leave the corrupt archive untouched")
658		}
659	}
