1	package main
2	
3	import (
4		"bytes"
5		"os"
6		"path/filepath"
7		"strings"
8		"testing"
9	
10		"github.com/gzhysuiioo/contractsentinel-audit/contractsentinel"
11	)
12	
13	// 本文件在真实命令行进程边界上回归保护 report / diff 读取已保存报告时对缺陷
14	// 记录文本成员的类型要求：findings 中每条记录已写出的 artifactHash、ruleId、
15	// version、severity、invariant、evidence 都必须是 JSON 字符串。把它们写成 null
16	// （或布尔值、数字、对象、数组）时，即使产物哈希、报告标识以及规则与缺陷的
17	// 对应关系仍吻合，整份归档也必须判为损坏——非零退出、原因进 stderr（含请求
18	// 的报告标识、记录在 findings 数组中从零开始的位置、出错成员名；记录的
19	// ruleId 本身是合法非空字符串时同时指出所属规则，并明确该成员必须是字符
20	// 串），stdout 不出现任何报告片段，原归档原样保留，不自动改写、删除或补齐。
21	// 成员省略或显式写成空字符串仍按既有必填与绑定要求判断；"Severity"、
22	// " evidence " 这类大小写变体或带空格名称只是扩展信息，其中的 null 既不触发
23	// 错误，也不能挽救非法的正式成员。diff 任一侧遇到同样的归档，也必须在输出
24	// 比较结果前整体失败，不能依据被当成空字符串的错误值计算分类或统计。
25	
26	// injectFindingField reads the archive named by id, locates the finding record
27	// with ruleID inside the findings array and rewrites the formal field member
28	// with the raw fragment (e.g. `null`); a record that does not carry the member
29	// gets it inserted right after the record's opening brace. The mutated bytes
30	// are written back and returned so tests can assert the failed read leaves
31	// them untouched.
32	func injectFindingField(t *testing.T, store, id, ruleID, field, fragment string) []byte {
33		t.Helper()
34		path := filepath.Join(store, id+".json")
35		data, err := os.ReadFile(path)
36		if err != nil {
37			t.Fatal(err)
38		}
39		doc := string(data)
40		findingsAt := strings.Index(doc, `"findings"`)
41		if findingsAt < 0 {
42			t.Fatal("test setup: archive has no findings member")
43		}
44		idMember := `"ruleId":"` + ruleID + `"`
45		idIdx := strings.Index(doc[findingsAt:], idMember)
46		if idIdx < 0 {
47			t.Fatalf("test setup: finding for rule %s not found in archive", ruleID)
48		}
49		idIdx += findingsAt
50		recStart := strings.LastIndexByte(doc[findingsAt:idIdx], '{')
51		if recStart < 0 {
52			t.Fatalf("test setup: finding for rule %s object has no start", ruleID)
53		}
54		recStart += findingsAt
55		recEnd := strings.IndexByte(doc[idIdx:], '}')
56		if recEnd < 0 {
57			t.Fatalf("test setup: finding for rule %s object has no end", ruleID)
58		}
59		recEnd += idIdx
60		marker := `"` + field + `":`
61		at := strings.Index(doc[recStart:recEnd], marker)
62		var out string
63		if at < 0 {
64			insertAt := recStart + 1
65			out = doc[:insertAt] + `"` + field + `":` + fragment + `,` + doc[insertAt:]
66		} else {
67			at += recStart
68			valueStart := at + len(marker)
69			var valueEnd int
70			if doc[valueStart] == '"' {
71				closing := strings.IndexByte(doc[valueStart+1:], '"')
72				if closing < 0 {
73					t.Fatalf("test setup: finding for rule %s %s value has no closing quote", ruleID, field)
74				}
75				valueEnd = valueStart + 1 + closing + 1
76			} else {
77				end := strings.IndexAny(doc[valueStart:], ",}")
78				if end < 0 {
79					t.Fatalf("test setup: finding for rule %s %s value has no end", ruleID, field)
80				}
81				valueEnd = valueStart + end
82			}
83			out = doc[:at] + `"` + field + `":` + fragment + doc[valueEnd:]
84		}
85		if out == doc {
86			t.Fatal("test setup: injection did not change the archive")
87		}
88		if err := os.WriteFile(path, []byte(out), 0o644); err != nil {
89			t.Fatal(err)
90		}
91		return []byte(out)
92	}
93	
94	// assertFindingTextCorruptFailure asserts the full CLI failure contract for a
95	// non-string formal finding text member.
96	func assertFindingTextCorruptFailure(t *testing.T, stdout, stderr string, code int, id, position, rule, field string) {
97		t.Helper()
98		if code == 0 {
99			t.Fatal("an archive with a non-string finding text member must exit non-zero")
100		}
101		if !strings.Contains(stderr, "corrupt") {
102			t.Fatalf("stderr must classify the archive as corrupt:\n%s", stderr)
103		}
104		if !strings.Contains(stderr, id) {
105			t.Fatalf("stderr must name the requested report id %q:\n%s", id, stderr)
106		}
107		if !strings.Contains(stderr, position) {
108			t.Fatalf("stderr must name the findings array position %q:\n%s", position, stderr)
109		}
110		if rule != "" && !strings.Contains(stderr, rule) {
111			t.Fatalf("stderr must name the owning rule %q:\n%s", rule, stderr)
112		}
113		if !strings.Contains(stderr, field+" must be a string") {
114			t.Fatalf("stderr must state %s must be a string:\n%s", field, stderr)
115		}
116		if stdout != "" {
117			t.Fatalf("rejected read must print nothing to stdout, got:\n%s", stdout)
118		}
119	}
120	
121	// --- report：六个正式成员写成 null 都失败；ruleId 本身非法时只按位置定位 ---
122	
123	func TestCLIReportNullFindingFieldsFailCleanly(t *testing.T) {
124		for _, tc := range []struct {
125			field string
126			rule  string // ruleId 本身非法时没有可点名的规则标识
127		}{
128			{"artifactHash", "rule-defect"},
129			{"ruleId", ""},
130			{"version", "rule-defect"},
131			{"severity", "rule-defect"},
132			{"invariant", "rule-defect"},
133			{"evidence", "rule-defect"},
134		} {
135			t.Run(tc.field, func(t *testing.T) {
136				bin := auditBinary(t)
137				work := t.TempDir()
138				store := filepath.Join(work, "reports")
139				id := auditOneReport(t, bin, work, store)
140				mutated := injectFindingField(t, store, id, "rule-defect", tc.field, `null`)
141	
142				stdout, stderr, code := runCLIReport(t, bin, store, id)
143				assertFindingTextCorruptFailure(t, stdout, stderr, code, id, "findings[0]", tc.rule, tc.field)
144				for _, marker := range []string{`"reportId"`, `"rules"`, `"findings"`, contractsentinel.StatusDefect} {
145					if strings.Contains(stdout, marker) {
146						t.Fatalf("stdout must not leak a report fragment %q:\n%s", marker, stdout)
147					}
148				}
149	
150				// 归档必须原样保留，不被自动修补或补齐。
151				kept, err := os.ReadFile(filepath.Join(store, id+".json"))
152				if err != nil {
153					t.Fatal(err)
154				}
155				if !bytes.Equal(kept, mutated) {
156					t.Fatalf("failed report read must leave the corrupt archive untouched:\n%s", kept)
157				}
158			})
159		}
160	}
161	
162	// --- report：布尔值、数字、对象、数组都同样判为损坏，不能默认成空字符串 ---
163	
164	func TestCLIReportNonStringFindingFieldsFailCleanly(t *testing.T) {
165		for _, field := range []string{"severity", "invariant", "evidence"} {
166			for _, val := range []string{`true`, `0`, `{}`, `[]`} {
167				t.Run(field+" "+val, func(t *testing.T) {
168					bin := auditBinary(t)
169					work := t.TempDir()
170					store := filepath.Join(work, "reports")
171					id := auditOneReport(t, bin, work, store)
172					injectFindingField(t, store, id, "rule-defect", field, val)
173	
174					stdout, stderr, code := runCLIReport(t, bin, store, id)
175					assertFindingTextCorruptFailure(t, stdout, stderr, code, id, "findings[0]", "rule-defect", field)
176				})
177			}
178		}
179	}
180	
181	// --- 核心场景：规则与缺陷记录都把 severity 保存为空字符串的合法报告，只把
182	// finding 的 severity 改成 null，标识不变也必须失败；diff 不能判成“无变化” ---
183	
184	func emptySeverityCLIInput(hash string) cliWireInput {
185		return cliWireInput{
186			Artifact: mixedCheckArtifact(),
187			Rules: []cliWireRule{
188				{ID: "g-empty", Kind: "static", Severity: "", Invariant: "", Version: "1"},
189			},
190			Checks: []cliWireCheck{
191				{ArtifactHash: hash, RuleID: "g-empty", Version: "1", Status: contractsentinel.StatusDefect, Note: "empty-text counterexample"},
192			},
193		}
194	}
