196	func auditEmptySeverityReport(t *testing.T, bin, work, store string) string {
197		t.Helper()
198		input := writeStructInput(t, work, "empty.json", emptySeverityCLIInput(mixedArtifactHash(t)))
199		stdout, stderr, code := runCLIAudit(t, bin, input, store)
200		if code != 0 {
201			t.Fatalf("setup audit of empty-text report must succeed: %s", stderr)
202		}
203		return decodeReport(t, stdout).ReportID
204	}
205	
206	func TestCLIReportNullEmptyTextFindingSeverityFailsCleanly(t *testing.T) {
207		bin := auditBinary(t)
208		work := t.TempDir()
209		store := filepath.Join(work, "reports")
210		id := auditEmptySeverityReport(t, bin, work, store)
211		path := filepath.Join(store, id+".json")
212		clean, err := os.ReadFile(path)
213		if err != nil {
214			t.Fatal(err)
215		}
216		mutated := injectFindingField(t, store, id, "g-empty", "severity", `null`)
217	
218		// null 被洗成 ""：归档标识必须保持与合法空文本报告一致，拒绝只能来自
219		// 类型关，而不是 id 不匹配。
220		if !bytes.Contains(mutated, []byte(`"severity":null`)) {
221			t.Fatalf("test setup: archive must carry the null finding severity:\n%s", mutated)
222		}
223		stdout, stderr, code := runCLIReport(t, bin, store, id)
224		assertFindingTextCorruptFailure(t, stdout, stderr, code, id, "findings[0]", "g-empty", "severity")
225	
226		// 即使把这份归档与它自身比较，也必须整体失败，而不是读出“无变化”。
227		diffOut, diffErr, diffCode := runCLIDiff(t, bin, store, id, id)
228		if diffCode == 0 {
229			t.Fatal("diff must not read 无变化 from a null severity laundered into empty text")
230		}
231		if !strings.Contains(diffErr, "corrupt") || !strings.Contains(diffErr, id) ||
232			!strings.Contains(diffErr, "g-empty") || !strings.Contains(diffErr, "severity must be a string") {
233			t.Fatalf("diff stderr must name the corrupt report, record, rule and string requirement:\n%s", diffErr)
234		}
235		if diffOut != "" || strings.Contains(diffOut, contractsentinel.ChangeNoChange) {
236			t.Fatalf("diff stdout must stay empty and never render 无变化:\n%s", diffOut)
237		}
238	
239		// 恢复为合法空文本归档后，report 与自比较都成功，且归档字节不被重写。
240		if err := os.WriteFile(path, clean, 0o644); err != nil {
241			t.Fatal(err)
242		}
243		if _, _, code := runCLIReport(t, bin, store, id); code != 0 {
244			t.Fatal("the restored legal empty-text report must load")
245		}
246		if diffOut, _, code := runCLIDiff(t, bin, store, id, id); code != 0 {
247			t.Fatalf("restored report must diff against itself: %s", diffOut)
248		} else if !strings.Contains(diffOut, contractsentinel.ChangeNoChange) {
249			t.Fatalf("a legal report compared with itself must show 无变化:\n%s", diffOut)
250		}
251		kept, err := os.ReadFile(path)
252		if err != nil {
253			t.Fatal(err)
254		}
255		if !bytes.Equal(kept, clean) {
256			t.Fatal("reads must not rewrite the restored archive")
257		}
258	}
259	
260	// --- report：变体名称中的 null 是扩展信息，既不触发错误也不能挽救正式 null ---
261	
262	func TestCLIReportFindingTextVariantRules(t *testing.T) {
263		bin := auditBinary(t)
264		work := t.TempDir()
265		store := filepath.Join(work, "reports")
266		id := auditOneReport(t, bin, work, store)
267	
268		// 变体携带 null：仍是一份合法报告，缺陷记录按正式成员原样读回。
269		injectFindingField(t, store, id, "rule-defect", "Severity", `null`)
270		stdout, stderr, code := runCLIReport(t, bin, store, id)
271		if code != 0 {
272			t.Fatalf("a case-variant extension member must not corrupt the report: %s", stderr)
273		}
274		decoded := decodeReport(t, stdout)
275		if len(decoded.Findings) != 1 || decoded.Findings[0].Severity != "high" {
276			t.Fatalf("a variant member must not supply the formal finding severity: %+v", decoded.Findings)
277		}
278	
279		// 正式成员为 null、旁边的变体写了合法字符串（位于其前或其后）都必须失败。
280		for _, pos := range []string{"before", "after"} {
281			t.Run(pos, func(t *testing.T) {
282				sub := t.TempDir()
283				subStore := filepath.Join(sub, "reports")
284				subID := auditOneReport(t, bin, sub, subStore)
285				if pos == "before" {
286					injectFindingField(t, subStore, subID, "rule-defect", "severity", `null`)
287					injectFindingField(t, subStore, subID, "rule-defect", "Severity", `"critical"`)
288				} else {
289					injectFindingField(t, subStore, subID, "rule-defect", "severity",
290						`null,"Severity":"critical"`)
291				}
292				out, errText, exitCode := runCLIReport(t, bin, subStore, subID)
293				assertFindingTextCorruptFailure(t, out, errText, exitCode, subID, "findings[0]", "rule-defect", "severity")
294			})
295		}
296	}
297	
298	// --- diff：任一侧归档含 null 缺陷记录文本成员，比较前失败且不输出局部结果 ---
299	
300	func TestCLIDiffNullFindingTextEitherSideFailsCleanly(t *testing.T) {
301		bin := auditBinary(t)
302		work := t.TempDir()
303		store := filepath.Join(work, "reports")
304	
305		// 一侧是常规混合状态报告；另一侧是 severity/invariant 均为空字符串的合法
306		// 报告，损坏后 null 会被洗成 "" 且归档标识保持不变。
307		goodID := auditOneReport(t, bin, work, store)
308		emptyID := auditEmptySeverityReport(t, bin, work, store)
309		cleanEmpty, err := os.ReadFile(filepath.Join(store, emptyID+".json"))
310		if err != nil {
311			t.Fatal(err)
312		}
313		mutated := injectFindingField(t, store, emptyID, "g-empty", "severity", `null`)
314	
315		// 第二份损坏。
316		stdout, stderr, code := runCLIDiff(t, bin, store, goodID, emptyID)
317		if code == 0 {
318			t.Fatal("diff must exit non-zero when the second report carries a null finding severity")
319		}
320		if !strings.Contains(stderr, "corrupt") || !strings.Contains(stderr, emptyID) ||
321			!strings.Contains(stderr, "g-empty") || !strings.Contains(stderr, "findings[0]") ||
322			!strings.Contains(stderr, "severity must be a string") {
323			t.Fatalf("stderr must name the corrupt report, position, rule and string requirement:\n%s", stderr)
324		}
325		if stdout != "" {
326			t.Fatalf("stdout must be empty on failure, got:\n%s", stdout)
327		}
328		for _, marker := range []string{`"results"`, `"summary"`, contractsentinel.ChangeNoChange, contractsentinel.ChangeRuleAdded} {
329			if strings.Contains(stdout, marker) {
330				t.Fatalf("stdout must not leak a partial diff %q:\n%s", marker, stdout)
331			}
332		}
333		if kept, err := os.ReadFile(filepath.Join(store, emptyID+".json")); err != nil || !bytes.Equal(kept, mutated) {
334			t.Fatalf("failed diff must leave the corrupt archive untouched: %v", err)
335		}
