337		// 第一份损坏、第二份恢复。
338		if err := os.WriteFile(filepath.Join(store, emptyID+".json"), cleanEmpty, 0o644); err != nil {
339			t.Fatal(err)
340		}
341		injectFindingField(t, store, goodID, "rule-defect", "evidence", `null`)
342		stdout, stderr, code = runCLIDiff(t, bin, store, goodID, emptyID)
343		if code == 0 {
344			t.Fatal("diff must exit non-zero when the first report carries a null finding evidence")
345		}
346		if !strings.Contains(stderr, goodID) || !strings.Contains(stderr, "rule-defect") ||
347			!strings.Contains(stderr, "evidence must be a string") {
348			t.Fatalf("stderr must name the corrupt first report, rule and string requirement:\n%s", stderr)
349		}
350		if stdout != "" {
351			t.Fatalf("stdout must stay empty on failure:\n%s", stdout)
352		}
353	
354		// 两侧都恢复后比较成功，且成功的比较不重写任何归档。
355		goodClean := auditOneReportToCleanBytes(t, bin, work)
356		if err := os.WriteFile(filepath.Join(store, goodID+".json"), goodClean, 0o644); err != nil {
357			t.Fatal(err)
358		}
359		if err := os.WriteFile(filepath.Join(store, emptyID+".json"), cleanEmpty, 0o644); err != nil {
360			t.Fatal(err)
361		}
362		stdout, stderr, code = runCLIDiff(t, bin, store, goodID, emptyID)
363		if code != 0 {
364			t.Fatalf("restored archives must diff successfully: %s", stderr)
365		}
366		if !strings.Contains(stdout, `"results"`) || !strings.Contains(stdout, `"summary"`) {
367			t.Fatalf("restored diff must print the full comparison:\n%s", stdout)
368		}
369		keptGood, err := os.ReadFile(filepath.Join(store, goodID+".json"))
370		if err != nil {
371			t.Fatal(err)
372		}
373		keptEmpty, err := os.ReadFile(filepath.Join(store, emptyID+".json"))
374		if err != nil {
375			t.Fatal(err)
376		}
377		if !bytes.Equal(keptGood, goodClean) || !bytes.Equal(keptEmpty, cleanEmpty) {
378			t.Fatal("successful diff must not rewrite either archive")
379		}
380	}
381	
382	// auditOneReportToCleanBytes audits the standard mixed report into a fresh
383	// store and returns its clean archive bytes, so a corrupted main-store copy can
384	// be restored to exactly what audit would have written.
385	func auditOneReportToCleanBytes(t *testing.T, bin, work string) []byte {
386		t.Helper()
387		cleanStore := filepath.Join(work, "clean-restore")
388		cleanID := auditOneReport(t, bin, work, cleanStore)
389		data, err := os.ReadFile(filepath.Join(cleanStore, cleanID+".json"))
390		if err != nil {
391			t.Fatal(err)
392		}
